using FamilyVeda.Application.Auth;
using FamilyVeda.Application.Common;
using FluentValidation;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.RateLimiting;

namespace FamilyVeda.Api.Controllers;

[Route("api/v1/auth")]
[EnableRateLimiting("Auth")]
public sealed class AuthController(IAuthService authService) : ApiControllerBase
{
    [HttpPost("register")]
    [AllowAnonymous]
    [ProducesResponseType<AuthResponse>(StatusCodes.Status201Created)]
    public async Task<ActionResult<AuthResponse>> Register(
        RegisterRequest request,
        IValidator<RegisterRequest> validator,
        CancellationToken cancellationToken)
    {
        await ValidateAsync(validator, request, cancellationToken);
        var response = await authService.RegisterAsync(request, cancellationToken);
        return Created($"/api/v1/users/{response.UserId}", response);
    }

    [HttpPost("login")]
    [AllowAnonymous]
    public async Task<ActionResult<AuthResponse>> Login(
        LoginRequest request,
        IValidator<LoginRequest> validator,
        CancellationToken cancellationToken)
    {
        await ValidateAsync(validator, request, cancellationToken);
        return Ok(await authService.LoginAsync(request, cancellationToken));
    }

    [HttpPost("refresh")]
    [AllowAnonymous]
    public async Task<ActionResult<AuthResponse>> Refresh(RefreshRequest request, CancellationToken cancellationToken) =>
        Ok(await authService.RefreshAsync(request, cancellationToken));

    [HttpPost("logout")]
    [Authorize]
    public async Task<IActionResult> Logout(CancellationToken cancellationToken)
    {
        await authService.LogoutAsync(cancellationToken);
        return NoContent();
    }

    [HttpPost("forgot-password")]
    [AllowAnonymous]
    public async Task<ActionResult<ResetPasswordResponse>> ForgotPassword(
        ForgotPasswordRequest request,
        IValidator<ForgotPasswordRequest> validator,
        CancellationToken cancellationToken)
    {
        await ValidateAsync(validator, request, cancellationToken);
        return Ok(await authService.ForgotPasswordAsync(request, cancellationToken));
    }

    [HttpPost("reset-password")]
    [AllowAnonymous]
    public async Task<ActionResult<ResetPasswordResponse>> ResetPassword(
        ResetPasswordRequest request,
        IValidator<ResetPasswordRequest> validator,
        CancellationToken cancellationToken)
    {
        await ValidateAsync(validator, request, cancellationToken);
        return Ok(await authService.ResetPasswordAsync(request, cancellationToken));
    }

    [HttpPost("change-password")]
    [Authorize]
    public async Task<IActionResult> ChangePassword(
        ChangePasswordRequest request,
        IValidator<ChangePasswordRequest> validator,
        CancellationToken cancellationToken)
    {
        await ValidateAsync(validator, request, cancellationToken);
        await authService.ChangePasswordAsync(request, cancellationToken);
        return NoContent();
    }

    [HttpGet("admin/users")]
    [Authorize(Policy = "Admin")]
    public async Task<ActionResult<PagedResult<AdminUserDto>>> GetAdminUsers(
        [FromQuery] int page = 1,
        [FromQuery] int pageSize = 20,
        [FromQuery] string? search = null,
        CancellationToken cancellationToken = default)
    {
        return Ok(await authService.GetAdminUsersAsync(page, pageSize, search, cancellationToken));
    }

    [HttpPost("admin/users/{userId:guid}/reset-password")]
    [Authorize(Policy = "Admin")]
    public async Task<ActionResult<ResetPasswordResponse>> AdminResetPassword(
        Guid userId,
        AdminResetPasswordRequest request,
        CancellationToken cancellationToken)
    {
        return Ok(await authService.AdminResetPasswordAsync(userId, request, cancellationToken));
    }

    [HttpPost("admin/users/{userId:guid}/toggle-status")]
    [Authorize(Policy = "Admin")]
    public async Task<ActionResult<AdminUserDto>> AdminToggleStatus(
        Guid userId,
        AdminToggleStatusRequest request,
        CancellationToken cancellationToken)
    {
        return Ok(await authService.AdminToggleUserStatusAsync(userId, request, cancellationToken));
    }
}
